    "review_comment": "The markdown rendering process uses remarkable library which may be subject to certain security issues with malformed input. It's important to note that this is a new library (changed from marked to remarkable) and should be audited for CVEs or known issues.",
    "line_snippet": "callback(undefined, parser.render(raw));",
    "vuln_type": [
      "CWE-476"
    ]
  }
]

